class BowlingGame:
    def __init__(self):
        self.rolls = []
        self.frames = 0
        self.frame_rolls = []

    def roll(self, pins):
        if pins < 0 or pins > 10:
            raise ValueError("Pins knocked down must be between 0 and 10")
        if self.frames == 10:
            raise ValueError("Cannot roll after the game is over")

        if self.frames < 9:
            if len(self.frame_rolls) == 1 and self.frame_rolls[0] + pins > 10:
                raise ValueError(
                    "Two rolls in a frame cannot score more than 10 points"
                )
        else:
            # Tenth frame: a strike allows two bonus rolls, a spare one.
            if len(self.frame_rolls) == 2:
                first, second = self.frame_rolls
                if first < 10 and first + second < 10:
                    raise ValueError("Cannot roll after the game is over")
                if first == 10 and second < 10 and second + pins > 10:
                    raise ValueError(
                        "Bonus rolls after a strike cannot score more than 10 points"
                    )

        self.rolls.append(pins)
        self.frame_rolls.append(pins)
        if self._frame_complete():
            self.frames += 1
            self.frame_rolls = []

    def _frame_complete(self):
        rolls = self.frame_rolls
        if self.frames < 9:
            return len(rolls) == 2 or (len(rolls) == 1 and rolls[0] == 10)
        # Tenth frame
        if len(rolls) == 1:
            return False
        if len(rolls) == 2:
            return not (rolls[0] == 10 or rolls[0] + rolls[1] == 10)
        return True

    def score(self):
        if self.frames != 10:
            raise ValueError("Cannot score an incomplete game")
        rolls = self.rolls
        total = 0
        i = 0
        for _ in range(10):
            if rolls[i] == 10:
                total += 10 + rolls[i + 1] + rolls[i + 2]
                i += 1
            elif rolls[i] + rolls[i + 1] == 10:
                total += 10 + rolls[i + 2]
                i += 2
            else:
                total += rolls[i] + rolls[i + 1]
                i += 2
        return total
